"""Render the evidence README from measured JSON. Does not rerun the experiment."""
import json,hashlib,shutil,subprocess
from pathlib import Path
from run import EVID,SCR,BASE,INPUT,HERE,dump

fmt=lambda x:f'{x:.6g}'
def load(n):return json.loads((EVID/n).read_text())
def maxstats(name,variant,mixed):
 r=[a for a in load(name+'-crack-summary.json') if a['variant']==variant and (a['depth_a']<a['depth_b'])==mixed]
 return dict(pairs=sum(x['pairs'] for x in r),max=max(x['max_m'] for x in r),p99=max(x['p99_m'] for x in r),ratio=max(x['max_fraction_ge'] for x in r),p99ratio=max(x['p99_fraction_ge'] for x in r),missing=sum(x['missing_exact_edges'] for x in r))
def report():
 tex=load('tex3-levels.json');crop=load('crop3-levels.json');tb=load('tex3-build.json');cb=load('crop3-build.json')
 t=next(r for r in tex if r['depth']==0 and r['variant']=='candidate');b=next(r for r in tex if r['depth']==0 and r['variant']=='baseline');c=crop[0]
 basecpu=154/(788425/1e6);basepeak=4.09*(1<<30);cr=maxstats('tex3','baseline',True)
 baseline_stdout=json.loads((EVID/'baseline-stdout.json').read_text());baseline_diag=baseline_stdout['diagnostics']
 text=['| Metric | tex3 UV-downscale | tex3 current baseline | crop3 UV-downscale |','|---|---:|---:|---:|',f"| Coarse construction CPU-s / Mtri | {tb['cpu_s']:.3f} / {tb['cpu_s_per_mtri']:.3f} | Not isolated; whole tiler 154 / {basecpu:.3f} | {cb['cpu_s']:.3f} / {cb['cpu_s_per_mtri']:.3f} |",f"| Root triangles | {t['frontier_triangles']:,} | {b['frontier_triangles']:,} | {c['frontier_triangles']:,} |",f"| Root sampled geometry mean / p95 / max (m) | {' / '.join(fmt(t['geometry_two_sided_m'][k]) for k in ['mean','p95','max'])} | {' / '.join(fmt(b['geometry_two_sided_m'][k]) for k in ['mean','p95','max'])} | {' / '.join(fmt(c['geometry_two_sided_m'][k]) for k in ['mean','p95','max'])} |",f"| Root mean ΔE76 / PSNR dB | {t['mean_deltaE76']:.3f} / {t['psnr_db']:.2f} | {b['mean_deltaE76']:.3f} / {b['psnr_db']:.2f} | {c['mean_deltaE76']:.3f} / {c['psnr_db']:.2f} |",f"| Mixed-depth max gap (m) | 0 (778 pairs) | {cr['max']:.6f} (778 pairs) | 0 ({maxstats('crop3','candidate',True)['pairs']} pairs) |",f"| Root GLB bytes | {t['level_glb_bytes']:,} | {b['level_glb_bytes']:,} | {c['level_glb_bytes']:,} |",'',
 '**Verdict: reject this strict UV/chart/border-locking variant as a drop-in replacement.** It removes the expensive source-surface texture query and is crack-free on these inputs, but tex3 stalls at 244,945 triangles at depth 3 and does not shrink at depths 2 or 1. The root has 244,947 triangles: 29.9× the 8192 cap and 52.2× the current root. Repeated texture downscaling also loses substantial detail. Crop3 has the same budget problem (216,221 root triangles, 26.4× cap), despite requiring no texture work.',
 '',f"The corrected tex3 construction is {tb['cpu_s']:.3f} CPU-s including {tb['child_texture_decode_cpu_s']:.3f} CPU-s of KTX2 transcoding and {tb['leaf_mesh_decode_cpu_s']:.3f} CPU-s of leaf mesh decoding. This is {154/tb['cpu_s']:.2f}× below the cached **whole-tiler** 154 CPU-s; it is not a controlled coarse-only speedup. The cached baseline stdout separately reports {baseline_diag['proxy_bake']['raster_worker_seconds']:.3f} raster worker-seconds plus chart/encode/assemble/commit work; those are worker elapsed timers, not process CPU. The prototype writes PNG + uncompressed FLOAT GLBs, whereas the baseline uses KTX2 + meshopt. CPU and bytes are therefore informative prototype measurements, not codec-matched production acceptance.",
 '', 'Primitive identity **is preserved**: each proxy primitive has a constant EXT_mesh_features ID resolving to the original `(mesh_index, primitive_index)` row in EXT_structural_metadata, and simplification never crosses those groups. Tex3 leaves are byte-for-byte copies, including their complete metadata, picking IDs and atlases. Crop3 leaves retain every original triangle, decoded position, normal and RGBA value; source primitive/triangle identity is explicit. `validation.json` and `tex3-leaf-copied-sha256.json` contain the executed checks.', '', '## All metrics by variant', '', 'Geometry/colour rows use the complete REPLACE frontier at each depth (shallower leaves included). Tile/triangle/byte counts are contents **at that exact depth**, with proxy counts in parentheses. Distances use 200,000 area-weighted source→frontier and 200,000 frontier→source samples at every level. Colour is base colour at the same 200,000 source samples, projected to the nearest proxy surface; bilinear filtering and BOX downscaling both operate in linear light. ΔE is CIELAB ΔE76, D65. Lighting, occlusion, anisotropy and mip selection are outside this surface-colour metric.', '']
 for name,var,title,rows,build in [('tex3','candidate','tex3 UV-downscale',tex,tb),('tex3','baseline','tex3 current baseline',tex,None),('crop3','candidate','crop3 UV-downscale',crop,cb)]:
  text += ['### '+title,'','| Metric / depth | Measured result |','|---|---|']
  if build:
   proc=load(name+'-process.json');text += [f"| Coarse user+sys CPU | {build['cpu_s']:.6f} s; {build['cpu_s_per_mtri']:.6f} s/Mtri; {build['wall_s']:.3f} s wall |",f"| Whole process cross-check | {proc['user_s']+proc['sys_s']:.6f} CPU-s; includes interpreter and full-detail leaf copy/assembly outside the coarse timer |",f"| Peak RSS | {max(proc['max_rss_bytes'],build['peak_rss_bytes'])/(1<<20):.2f} MiB (whole build process); coarse instrument {build['peak_rss_bytes']/(1<<20):.2f} MiB |",f"| Peak scratch | {build['peak_scratch_bytes']:,} bytes ({build['peak_scratch_bytes']/(1<<30):.3f} GiB), this input's preparation + fresh build; venv, other input and metrics excluded |"]
  else:text += [f'| CPU | Coarse process CPU unavailable in cached evidence. Whole tiler: 150 user + 4 sys = 154 s; {basecpu:.3f} s/Mtri; wall 59.7 s |',f"| Peak RSS / scratch | Cached whole-tiler RSS 4.09 GiB; stdout instrumented run scratch peak {baseline_diag['capture']['run_scratch_peak_bytes']:,} bytes; logical scratch peak {baseline_diag['capture']['scratch_logical_peak_bytes']:,} bytes (internal tiler accounting, unlike prototype directory occupancy) |"]
  for r in rows:
   if r['variant']!=var:continue
   d=r['depth'];g=r['geometry_two_sided_m'];text += [f"| d{d} contents | {r['level_tiles']} tiles ({r['proxy_tiles']} proxies); {r['level_triangles']:,} tris ({r['proxy_triangles']:,} proxy tris); {r['level_glb_bytes']:,} bytes |",f"| d{d} frontier geometry / colour | {r['frontier_triangles']:,} frontier tris; distance mean/p95/max {g['mean']:.6g} / {g['p95']:.6g} / {g['max']:.6g} m; mean ΔE76 {r['mean_deltaE76']:.4f}; PSNR {r['psnr_db']:.3f} dB |"]
  for mixed in [True,False]:
   cc=maxstats(name,var,mixed);proof=f"{cc['missing']} missing exact candidate seam edges" if var=='candidate' else 'baseline exact segment equality not asserted'
   text += [f"| {'Mixed-depth' if mixed else 'Same-depth'} cracks | {cc['pairs']} valid adjacent pairs; max {cc['max']:.8g} m; worst depth-pair pooled p99 {cc['p99']:.8g} m; max/GE {cc['ratio']:.8g}; worst depth-pair p99/GE {cc['p99ratio']:.8g}; {proof} |"]
  text += ['| Simulated first views | N/A: standalone content GLBs and tree index, no runnable tileset was built |','']
 text += ['## Triangle cost of locks','', 'Each paired ablation receives exactly the final variant’s merged child meshes. Geometry-only merges all identities and uses no attributes/explicit locks (diagnostic, not acceptable). UV/primitive control retains separate primitive groups and attributes but omits explicit locks; meshoptimizer may decimate seam chains. Final variant explicitly locks chart/attribute boundary vertices and uses LOCK_BORDER. These are conservative costs of this implementation, not a lower bound on every possible UV-preserving hierarchy.', '', '| Input | Depth | Child tris | Geometry only | UV/primitive, no explicit locks | UV + hard border locks | Extra versus geometry |', '|---|---:|---:|---:|---:|---:|---:|']
 for name,rs in [('tex3',tex),('crop3',crop)]:
  for r in reversed(rs):
   if r['variant']!='candidate' or not r['proxy_tiles']:continue
   text.append(f"| {name} | {r['depth']} | {r['input_triangles']:,} | {r['geometry_control_triangles']:,} | {r['uv_control_triangles']:,} | {r['proxy_triangles']:,} | {r['proxy_triangles']-r['geometry_control_triangles']:,} |")
 text += ['', '## Interpretation and limits','',
 'The tex3 geometry is unchanged from depths 3 through 0 (apart from two isolated leaf triangles joining the root). Additional changes in ΔE across those levels therefore expose cumulative downscale blur directly. The source’s existing atlas/codec error is retained: full-detail tex3 frontier colour has its own nonzero ΔE. Whole child pages are packed as chart blocks, including their existing gutters and unused pixels, with two extra extruded pixels. This avoids any source re-bake but is deliberately conservative in packing efficiency.', '',
 'The crack census welds source positions, finds every source-edge adjacency across leaf owners (including all face pairs on the 11 non-manifold source edges), then enumerates all disjoint ancestor combinations. Overlapping ancestor/descendant pairs cannot coexist in a REPLACE frontier and are excluded. Every decoded candidate interface segment exists exactly on both sides, proving continuous zero gap along those interfaces, not merely zero at samples. Source holes and disconnected surfaces do not introduce a cross-tile interface. This establishes source-topology surface adjacency; it does not classify every overlapping bounding-box pair or point-only contact.', '',
 'Baseline gaps are sampled in both directions: source edge endpoints and midpoints anchor projections onto each decoded open border, then the projected border points are queried against the opposite decoded surface. This measures separation rather than displacement of a shared seam from source. Per-pair max/p99 are in `*-crack-pairs.json`; pooled per-depth-pair metre and GE-fraction distributions are in `*-crack-summary.json`. The tables conservatively show the worst of the pooled p99 values, not a mislabeled global percentile. Baseline interface identification and maxima remain sampled; narrow unsampled excursions can be missed. Candidate zero is supported independently by exact segment presence.', '',
 'Candidate GE is an experimental monotone per-level envelope of the sampled maxima; it is not a Hausdorff certificate. Zero cracks normalize to zero regardless of that denominator. Baseline fractions use the published per-tile certified GE. The Open3D float32 BVH is translated before queries; the exact crop3 leaf geometry still shows a roughly 14 µm numerical maximum. Sampling cannot certify worst-case error. The crop3 split is a fresh centroid octree at 8192 leaf triangles; tex3 reuses the exact baseline tree and leaf split. No crop3 baseline was supplied or re-baked.', '',
 'This experiment supports removing source-surface texture queries from a cheap coarse builder. It does not support replacing today’s hierarchy with this strict-lock implementation: chart boundaries dominate geometry, late levels stall, and aggressive repeated downscaling blurs the top. Softer UV seam decimation reduces the tex3 root to about 56k triangles in the diagnostic control, still well above the cap; crack acceptance of that separate variant has not been established.', '',
 '## Reproduction and evidence','',
 'Source base: `8971c9c3`. Prototype is `bench/lod_uv_downscale/`; run `setup.sh`, then `setsid -f chrt -i 0 nice -n 19 bash bench/lod_uv_downscale/run.sh`. All sustained runs use idle scheduling and two math/BVH workers; the dedicated target directory is `/home/bend/.cache/rt-wt/target-lod-uv-downscale`, `CARGO_BUILD_JOBS=3`. The meshoptimizer 0.6.2 C ABI is compiled from the Cargo registry copy corresponding to Cargo.lock. Inputs are only tex3 and crop3. No browser, server or full-model run was used.', '',
 'JSON measurements, input/source hashes, complete Python environment, build/process logs, sensitive controls and independent review are beside this README. Published prototype GLBs and their per-file SHA-256 manifests are retained under `artifacts/`; prepared arrays, extracted images and the scratch venv are removed after acceptance. Source hashes and the pushed commit are recorded in `execution.json`. The original baseline timing record is copied as `baseline-measure.json`; baseline output identity is bound in `baseline-artifact-sha256.json`.', '']
 (EVID/'README.md').write_text('\n'.join(text))
 if __name__=='__main__':print(EVID/'README.md')

if __name__=='__main__':report()
